<!doctype html>
<html lang="pt-BR">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<meta name="description" content="Consulta de intimações para clientes — Jurifácil, um produto da SGM Empresarial">
<title>Consulta de intimações | Área do cliente</title>
<link rel="icon" type="image/svg+xml" href="/favicon.svg">
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Fraunces:wght@400;600;700&family=Manrope:wght@400;500;600;700&display=swap" rel="stylesheet">
<style>
:root{--bg:#090b10;--surface:rgba(255,255,255,.045);--strong:rgba(255,255,255,.075);--border:rgba(255,255,255,.1);--border2:rgba(255,255,255,.18);--ink:#f3f5f9;--soft:#aab1c2;--faint:#747b8c;--a:#7c6bff;--a2:#22d3ee;--grad:linear-gradient(135deg,var(--a),var(--a2));--display:"Fraunces",Georgia,serif;--body:"Manrope","Segoe UI",sans-serif;color-scheme:dark}
*{box-sizing:border-box}body{min-height:100vh;margin:0;color:var(--ink);background:var(--bg);font:15px/1.55 var(--body);-webkit-font-smoothing:antialiased}body:before{content:"";position:fixed;inset:0;z-index:-1;background:radial-gradient(720px 480px at 12% -10%,rgba(124,107,255,.22),transparent 60%),radial-gradient(680px 520px at 110% 15%,rgba(34,211,238,.16),transparent 55%),radial-gradient(900px 700px at 50% 120%,rgba(124,107,255,.12),transparent 60%),var(--bg)}button,input{font:inherit}button{cursor:pointer}a{color:inherit;text-decoration:none}[hidden]{display:none!important}.shell{width:min(1260px,100%);min-height:100vh;margin:auto}.topbar{min-height:92px;padding:16px clamp(18px,4vw,48px);display:flex;align-items:center;justify-content:space-between;gap:24px;border-bottom:1px solid var(--border);background:rgba(9,11,16,.72);backdrop-filter:blur(14px)}.brand{display:flex;align-items:center;gap:14px}.mark{width:44px;height:44px;flex:0 0 auto;display:grid;place-items:center;background:#f4f3f3;border-radius:12px;padding:5px}.mark img{width:100%;height:100%;object-fit:contain;border-radius:6px}.kicker{display:block;color:var(--soft);font-size:11px;font-weight:700;letter-spacing:.1em;text-transform:uppercase}.brand h1{margin:2px 0 0;font:600 clamp(20px,2.5vw,30px)/1.15 var(--display)}.back{padding:10px 18px;color:var(--soft);border:1px solid var(--border2);border-radius:999px;background:var(--surface);font-size:13px;font-weight:600}.back:hover{color:var(--a2);border-color:var(--a2)}main{padding:42px clamp(14px,4vw,48px) 48px}.intro{max-width:760px;margin-bottom:24px}.eyebrow{margin:0 0 8px;color:var(--a2);font-size:12px;font-weight:800;letter-spacing:.12em;text-transform:uppercase}.intro h2{margin:0 0 10px;font:600 clamp(27px,4vw,42px)/1.12 var(--display)}.intro p{margin:0;color:var(--soft)}.panel{border:1px solid var(--border);border-radius:18px;background:var(--surface);box-shadow:0 18px 55px rgba(0,0,0,.16);backdrop-filter:blur(12px)}.search{padding:30px 24px}.instruction{margin:0 0 24px;color:var(--soft);font-size:13px}.grid{display:grid;grid-template-columns:minmax(280px,1.4fr) minmax(320px,1fr) auto auto;gap:24px;align-items:end}.field{position:relative;height:54px;padding:18px 13px 7px;border:1px solid var(--border2);border-radius:10px;background:rgba(9,11,16,.42)}.field:focus-within{border-color:var(--a2);box-shadow:0 0 0 3px rgba(34,211,238,.1)}.field label{position:absolute;top:-8px;left:10px;padding:0 5px;color:var(--soft);background:#0d1017;font-size:12px}.field input{width:100%;height:27px;padding:0;color:var(--ink);border:0;outline:0;background:transparent}.field input::placeholder{color:#6e7585}.period{display:grid;grid-template-columns:1fr 14px 1fr;align-items:center;gap:5px}.period span{color:var(--faint);text-align:center}input[type=date]::-webkit-calendar-picker-indicator{filter:invert(1);opacity:.72}.btn{min-height:46px;padding:0 20px;display:inline-flex;align-items:center;justify-content:center;gap:8px;color:var(--ink);border:1px solid var(--border2);border-radius:999px;background:var(--strong);font-weight:700;white-space:nowrap}.btn:hover:not(:disabled){color:var(--a2);border-color:var(--a2);transform:translateY(-1px)}.primary{color:#0a0c12;border:0;background:var(--grad);box-shadow:0 8px 28px -8px rgba(124,107,255,.65)}.primary:hover:not(:disabled){color:#0a0c12}.btn:disabled{cursor:not-allowed;opacity:.45}.btn svg{width:19px;height:19px}.status{min-height:54px;margin-top:18px;padding:14px 17px;display:flex;align-items:center;gap:10px;color:var(--soft);border:1px solid var(--border);border-radius:10px;background:rgba(255,255,255,.025)}.status.error{color:#ff9d9d;border-color:rgba(255,157,157,.3)}.status.success{color:#86efac;border-color:rgba(134,239,172,.25)}.spinner{width:18px;height:18px;border:2px solid var(--border2);border-top-color:var(--a2);border-radius:50%;animation:spin .75s linear infinite}@keyframes spin{to{transform:rotate(360deg)}}.results{margin-top:18px;overflow:hidden}.results-head{min-height:62px;padding:12px 18px;display:flex;align-items:center;justify-content:space-between;gap:16px;border-bottom:1px solid var(--border)}.results h2{margin:0;font:600 21px var(--display)}.count{color:var(--soft);font-size:13px}.table-wrap{overflow-x:auto}table{width:100%;border-collapse:collapse}th,td{padding:14px 12px;border-bottom:1px solid var(--border);text-align:left;vertical-align:top}th{color:var(--soft);background:rgba(255,255,255,.035);font-size:11px;text-transform:uppercase;letter-spacing:.05em}tbody tr:hover{background:rgba(124,107,255,.045)}.process{color:var(--a2);font-weight:700;white-space:nowrap}.nowrap{white-space:nowrap}.actions{display:flex;gap:4px}.icon{width:35px;height:35px;padding:0;display:grid;place-items:center;color:var(--a2);border:1px solid transparent;border-radius:8px;background:transparent}.icon:hover{border-color:var(--border2);background:var(--strong)}.icon svg{width:20px;height:20px}.empty{padding:50px 20px;color:var(--faint);text-align:center}.pagination{padding:14px 18px;display:flex;justify-content:flex-end;align-items:center;gap:8px;border-top:1px solid var(--border)}.page-summary{margin-right:6px;color:var(--soft);font-size:13px}.page-btn{min-width:38px;min-height:36px;padding:0 12px}.page-number{min-width:36px;padding:0 8px}.page-number.current{color:#0a0c12;border:0;background:var(--grad)}.ellipsis{padding:0 3px;color:var(--faint)}.notice{margin:18px 3px 0;color:var(--faint);font-size:12px;line-height:1.6}dialog{width:min(900px,calc(100vw - 32px));height:min(760px,calc(100vh - 32px));padding:0;color:var(--ink);border:1px solid var(--border2);border-radius:18px;background:#10131b}dialog::backdrop{background:rgba(3,5,8,.78)}.modal{height:100%;display:grid;grid-template-rows:auto 1fr}.modal-head{padding:14px 18px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid var(--border)}.modal-head h2{margin:0;font:600 19px var(--display)}.modal-close{color:var(--ink);border:0;background:transparent;font-size:28px}#document-frame{width:100%;height:100%;border:0;background:#fff}
@media(max-width:980px){.grid{grid-template-columns:1fr 1fr}.grid .btn{width:100%}}@media(max-width:650px){.topbar{padding:14px 16px}.back{display:none}.mark{width:40px;height:40px}main{padding:30px 12px}.search{padding:26px 14px}.grid{grid-template-columns:1fr;gap:21px}.period{grid-template-columns:1fr}.period span{display:none}.field.period-field{height:84px}.results-head{align-items:flex-start;flex-direction:column}.pagination{justify-content:center;flex-wrap:wrap}.page-summary{width:100%;text-align:center}}
.grid{grid-template-columns:minmax(260px,1.4fr) minmax(150px,.65fr) minmax(150px,.65fr) auto auto;gap:20px}
input[type=date]::-webkit-calendar-picker-indicator{cursor:pointer}
@media(max-width:1100px){.grid{grid-template-columns:1fr 1fr}.grid .btn{width:100%}}
@media(max-width:650px){.grid{grid-template-columns:1fr}}
</style>
</head>
<body>
<div class="shell">
<header class="topbar"><div class="brand"><div class="mark" aria-hidden="true"><img src="/img/logo-sgm.png" alt=""></div><div><span class="kicker">SGM Empresarial</span><h1>Área do cliente</h1></div></div><a class="back" href="{{ route('login') }}">Voltar</a></header>
<main>
<section class="intro"><p class="eyebrow">Consulta individual</p><h2>Consulte suas intimações</h2><p>Informe seu nome completo e o período desejado. A pesquisa será feita somente entre as comunicações vinculadas ao escritório.</p></section>
<form id="search-form" class="search panel"><p class="instruction">Digite o nome completo da parte exatamente como consta no processo.</p><div class="grid">
<div class="field"><label for="client-name">Nome completo do cliente</label><input id="client-name" autocomplete="name" placeholder="Digite seu nome completo" minlength="5" required></div>
<div class="field"><label for="start-date">Data inicial</label><input id="start-date" type="date" required></div>
<div class="field"><label for="end-date">Data final</label><input id="end-date" type="date" required></div>
<button id="clear-search" class="btn" type="button">Limpar</button><button id="search-button" class="btn primary" type="submit"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" aria-hidden="true"><circle cx="11" cy="11" r="7"/><path d="m20 20-4-4"/></svg>Consultar</button>
</div></form>
<div id="status" class="status" role="status" aria-live="polite">Preencha seu nome completo para realizar a consulta.</div>
<section class="results panel" aria-labelledby="results-title"><div class="results-head"><h2 id="results-title">Suas intimações</h2><span id="result-count" class="count">0 itens exibidos</span></div><div class="table-wrap"><table><thead><tr><th>Processo</th><th>Tipo</th><th>Tribunal</th><th>Classe</th><th>Data de disponibilização</th><th>Ações</th></tr></thead><tbody id="results-body"></tbody></table><div id="empty-state" class="empty">Nenhuma consulta realizada.</div></div><nav id="pagination" class="pagination" aria-label="Paginação" hidden><span id="page-summary" class="page-summary">Página 1</span><button id="previous-page" class="btn page-btn" type="button" disabled>Anterior</button><span id="page-numbers"></span><button id="next-page" class="btn page-btn" type="button" disabled>Próxima</button></nav></section>
<p class="notice">Consulta informativa ao Diário de Justiça Eletrônico Nacional (DJEN). Nomes semelhantes podem gerar resultados imprecisos, e processos sigilosos podem não ser exibidos. Esta ferramenta não substitui a consulta aos sistemas oficiais nem a conferência dos prazos processuais.</p>
</main></div>
<dialog id="document-dialog"><div class="modal"><header class="modal-head"><h2 id="modal-title">Inteiro teor</h2><button id="modal-close" class="modal-close" type="button" aria-label="Fechar">×</button></header><iframe id="document-frame" sandbox="allow-popups" title="Inteiro teor da comunicação"></iframe></div></dialog>
<script>
(()=>{'use strict';
const API='https://comunicaapi.pje.jus.br/api/v1/comunicacao',OAB='84908',UF='PR',SIZE=100,state={items:[],total:0,page:1,loading:false,searched:false},$=s=>document.querySelector(s),form=$('#search-form'),nameInput=$('#client-name'),startDate=$('#start-date'),endDate=$('#end-date'),status=$('#status'),tbody=$('#results-body'),empty=$('#empty-state'),count=$('#result-count'),pagination=$('#pagination'),pageSummary=$('#page-summary'),pageNumbers=$('#page-numbers'),previous=$('#previous-page'),next=$('#next-page'),dialog=$('#document-dialog'),frame=$('#document-frame');
const iso=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`,normalize=v=>String(v||'').normalize('NFD').replace(/[̀-ͯ]/g,'').replace(/[^A-Z0-9 ]/gi,' ').replace(/\s+/g,' ').trim().toUpperCase();
function dates(){const d=new Date;startDate.value=iso(new Date(d.getFullYear(),d.getMonth(),1));endDate.value=iso(d)}
function setStatus(message,type=''){status.className=`status${type?` ${type}`:''}`;status.replaceChildren();if(type==='loading'){const s=document.createElement('span');s.className='spinner';status.append(s)}status.append(document.createTextNode(message))}
function dateBr(v){if(!v)return'—';const[y,m,d]=v.slice(0,10).split('-');return`${d}/${m}/${y}`}
const processMasked=i=>i.numeroprocessocommascara||i.numero_processo||'—';
function clientMatches(item,name){const wanted=normalize(name),tokens=wanted.split(' ').filter(x=>x.length>1),parties=Array.isArray(item.destinatarios)?item.destinatarios.map(x=>normalize(x.nome)):[];return tokens.length>=2&&parties.some(p=>tokens.every(token=>p.includes(token)))}
function isIntimation(item){return normalize(item.tipoComunicacao)==='INTIMACAO'}
const icon=p=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">${p}</svg>`;
function action(label,html,fn){const b=document.createElement('button');b.type='button';b.className='icon';b.title=label;b.setAttribute('aria-label',label);b.innerHTML=html;b.addEventListener('click',fn);return b}
function openDocument(i){$('#modal-title').textContent=`Inteiro teor — ${processMasked(i)}`;const safe=String(i.texto||'<p>Conteúdo não informado.</p>').replace(/<script[\s\S]*?<\/script>/gi,'').replace(/<iframe[\s\S]*?<\/iframe>/gi,'').replace(/<object[\s\S]*?<\/object>/gi,'').replace(/<embed[^>]*>/gi,'').replace(/\son\w+\s*=\s*(["']).*?\1/gi,'');frame.srcdoc=`<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><base target="_blank"><style>body{margin:24px;font:15px/1.55 Arial;color:#252a31}table{width:100%;border-collapse:collapse}td,th{padding:7px;border:1px solid #ddd}img{max-width:100%}</style></head><body>${safe}</body></html>`;dialog.showModal()}
function external(url){if(url&&/^https:\/\//i.test(url))window.open(url,'_blank','noopener,noreferrer')}
function sequence(current,total){if(total<=7)return Array.from({length:total},(_,i)=>i+1);const v=[...new Set([1,total,current-1,current,current+1])].filter(x=>x>=1&&x<=total).sort((a,b)=>a-b),r=[];v.forEach((x,i)=>{if(i&&x-v[i-1]>1)r.push('…');r.push(x)});return r}
function renderPagination(){const pages=Math.max(1,Math.ceil(state.total/SIZE));pagination.hidden=state.total<=SIZE;pageSummary.textContent=`Página ${state.page} de ${pages}`;previous.disabled=state.loading||state.page<=1;next.disabled=state.loading||state.page>=pages;pageNumbers.replaceChildren();sequence(state.page,pages).forEach(x=>{if(x==='…'){const e=document.createElement('span');e.className='ellipsis';e.textContent=x;pageNumbers.append(e);return}const b=document.createElement('button');b.type='button';b.className=`btn page-btn page-number${x===state.page?' current':''}`;b.textContent=x;b.disabled=state.loading||x===state.page;b.setAttribute('aria-label',`Ir para a página ${x}`);b.addEventListener('click',()=>search(x));pageNumbers.append(b)})}
function render(){tbody.replaceChildren();empty.hidden=state.items.length>0;empty.textContent=state.searched?'Nenhuma intimação foi encontrada para o nome e período informados.':'Nenhuma consulta realizada.';state.items.forEach(i=>{const row=document.createElement('tr'),vals=[{t:processMasked(i),c:'process'},{t:i.tipoComunicacao||'—'},{t:i.siglaTribunal||'—',c:'nowrap'},{t:i.nomeClasse||'—'},{t:dateBr(i.data_disponibilizacao),c:'nowrap'}];vals.forEach(v=>{const td=document.createElement('td');td.textContent=v.t;if(v.c)td.className=v.c;row.append(td)});const td=document.createElement('td');td.className='actions';td.append(action('Visualizar inteiro teor',icon('<path d="M2 12s3.5-6 10-6 10 6 10 6-3.5 6-10 6S2 12 2 12Z"/><circle cx="12" cy="12" r="2.5"/>'),()=>openDocument(i)));if(i.hash)td.append(action('Abrir certidão',icon('<path d="M6 2h8l4 4v16H6z"/><path d="M14 2v5h5M9 13h6M9 17h6"/>'),()=>external(`${API}/${encodeURIComponent(i.hash)}/certidao`)));if(i.link)td.append(action('Abrir no tribunal',icon('<path d="M14 3h7v7M10 14 21 3"/><path d="M21 14v5a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h5"/>'),()=>external(i.link)));row.append(td);tbody.append(row)});count.textContent=`${state.items.length} ${state.items.length===1?'item exibido':'itens exibidos'}`;renderPagination()}
function validate(){const name=nameInput.value.trim(),words=normalize(name).split(' ').filter(x=>x.length>1);if(words.length<2)throw Error('Informe o nome completo, com pelo menos nome e sobrenome.');if(!startDate.value||!endDate.value)throw Error('Informe as datas inicial e final.');if(startDate.value>endDate.value)throw Error('A data inicial não pode ser posterior à data final.');return name}
async function search(page=1){if(state.loading)return;try{const name=validate();state.loading=true;state.page=page;render();setStatus('Consultando o Diário da Justiça…','loading');$('#search-button').disabled=true;const q=new URLSearchParams({numeroOab:OAB,ufOab:UF,nomeParte:name,dataDisponibilizacaoInicio:startDate.value,dataDisponibilizacaoFim:endDate.value,meio:'D',pagina:String(page),itensPorPagina:String(SIZE)}),controller=new AbortController,timer=setTimeout(()=>controller.abort(),30000),response=await fetch(`${API}?${q}`,{headers:{Accept:'application/json'},signal:controller.signal});clearTimeout(timer);if(!response.ok)throw Error(`O serviço respondeu com o código ${response.status}. Tente novamente.`);const data=await response.json();if(!Array.isArray(data.items))throw Error('A resposta do serviço não possui o formato esperado.');state.items=data.items.filter(i=>isIntimation(i)&&clientMatches(i,name));state.total=Number(data.count||state.items.length);state.searched=true;render();setStatus(state.items.length?`${state.items.length} intimação(ões) correspondente(s) nesta página.`:'Nenhuma intimação correspondente foi encontrada.','success');if(page>1)$('.results').scrollIntoView({behavior:'smooth',block:'start'})}catch(e){state.items=[];state.total=0;state.searched=true;render();setStatus(e.name==='AbortError'?'A consulta demorou mais de 30 segundos. Tente novamente.':e.message||'Não foi possível consultar o serviço.','error')}finally{state.loading=false;$('#search-button').disabled=false;render()}}
form.addEventListener('submit',e=>{e.preventDefault();search(1)});nameInput.addEventListener('input',()=>nameInput.value=nameInput.value.replace(/\s{2,}/g,' '));$('#clear-search').addEventListener('click',()=>{nameInput.value='';dates();state.items=[];state.total=0;state.searched=false;render();setStatus('Preencha seu nome completo para realizar a consulta.');nameInput.focus()});previous.addEventListener('click',()=>search(state.page-1));next.addEventListener('click',()=>search(state.page+1));$('#modal-close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close()});dialog.addEventListener('close',()=>frame.srcdoc='');dates();render();
})();
</script>
</body>
</html>
